/* Public catalogue index. Runs searches away from the main UI thread. */
let sources=[],manifest,ready;
const types=['Skill','MCP Server','Plugin','Product','Agent Package','Command','Workflow Template','Repository'];
const categories=['Skills','MCP Servers','Marketplaces','Products','Agents','Commands','Workflows','Repositories'];
function title(path){let leaf=path.split('/').pop();try{leaf=decodeURIComponent(leaf);}catch{}return leaf.replace(/[-_]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase());}
function nameOf(row){return row[2]?.name||title(row[1]);}
function asRecord(si,ri){const row=sources[si][ri],m=row[2]||{},s=manifest.sources[si],url='https://'+s.host+row[1],parts=row[1].split('/').filter(Boolean),name=nameOf(row),kind=types[row[0]],indexed=!row[2];return {
 id:'import-'+si+'-'+ri.toString(36),name,mark:name.slice(0,2),type:kind,category:categories[row[0]],sourceCategory:m.category||'',owner:m.owner||((si===0||si===1)&&parts.length>=3?parts[1]:s.name),source:m.source||url,listingUrl:url,sourceSite:s.name,sourceId:si,imported:true,indexOnly:indexed,
 icon:m.icon||'',iconKind:m.icon?'Publisher avatar / source-provided image':'Resource type icon',official:!!m.official,license:m.license||'See original source',summary:m.summary||'Indexed in '+s.name+'. Open the original listing for publisher details.',description:m.summary||(!indexed?'Public catalogue metadata imported from '+s.name+'. Open the publisher documentation for full package contents and setup instructions.':'This entry is preserved from the public '+s.name+' listing index. Its description, package files, logo and installation instructions have not been imported. The title is derived from its URL; the original listing is linked below.'),capabilities:['Browse the original '+kind.toLowerCase()+' listing','Inspect publisher documentation','Save and compare this resource'],tags:[kind,s.name,m.owner||''],demo:false,order:ri,status:indexed?'Index entry':'Catalogue metadata',ownership:'Third-party listing',commercial:'See publisher pricing and terms',docs:m.source||url,runtime:'See source documentation',compatibility:'Not independently tested',risk:'See publisher permissions and configuration',last_verified_at:manifest.captured,source_status:indexed?'public_index':'public_catalogue_metadata',security_review_status:'not_audited',acquisition_status:indexed?'index_only':'metadata_only',execution_status:'not_executed',installCommand:m.installCommand||''
};}
async function load(){manifest=await (await fetch('./catalogue/manifest.json')).json();sources=await Promise.all(manifest.sources.map(s=>fetch('./catalogue/'+s.file).then(r=>{if(!r.ok)throw Error('Catalogue '+s.name+' failed to load');return r.json();})));return manifest;}
ready=load();
self.onmessage=async({data:q})=>{try{await ready;if(q.action==='init'){postMessage({request:q.request,manifest});return;}if(q.action==='get'){const m=/^import-(\d+)-([a-z0-9]+)$/.exec(q.id);const record=m&&sources[+m[1]]?.[parseInt(m[2],36)]?asRecord(+m[1],parseInt(m[2],36)):null;postMessage({request:q.request,record});return;}
 const matches=[],words=(q.query||'').trim().toLowerCase().split(/\s+/).filter(Boolean),wanted=q.types||[],siFilter=q.source??'all',category=q.category||'All',saved=q.savedOnly?new Set(q.saved||[]):null;
 for(let si=0;si<sources.length;si++){if(siFilter!=='all'&&+siFilter!==si)continue;const rows=sources[si];for(let ri=0;ri<rows.length;ri++){const row=rows[ri],m=row[2],typ=types[row[0]];if(wanted.length&&!wanted.includes(typ))continue;if(category!=='All'&&category!==categories[row[0]]&&category!==m?.category)continue;if(q.metadataOnly&&!m)continue;if(q.officialOnly&&!m?.official)continue;if(saved&&!saved.has('import-'+si+'-'+ri.toString(36)))continue;if(words.length){const hay=(row[1]+' '+(m?.name||'')+' '+(m?.summary||'')+' '+(m?.owner||'')+' '+typ).toLowerCase();if(!words.every(w=>hay.includes(w)))continue;}matches.push([si,ri]);}}
 if(q.sort==='az')matches.sort((a,b)=>nameOf(sources[a[0]][a[1]]).localeCompare(nameOf(sources[b[0]][b[1]])));
 else if(q.sort==='type')matches.sort((a,b)=>sources[a[0]][a[1]][0]-sources[b[0]][b[1]][0]);
 else matches.sort((a,b)=>Number(!!sources[b[0]][b[1]][2])-Number(!!sources[a[0]][a[1]][2]));
 const limit=Math.min(100,q.limit||24),pages=Math.max(1,Math.ceil(matches.length/limit)),page=Math.min(Math.max(1,q.page||1),pages),records=matches.slice((page-1)*limit,page*limit).map(([s,r])=>asRecord(s,r));postMessage({request:q.request,total:matches.length,page,pages,records});
 }catch(e){postMessage({request:q.request,error:e.message});}};
